import { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios'; // Import ajouté
import './JobDetails.css';

export default function JobDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [job, setJob] = useState(null);
  const fileInputRef = useRef(null); 

  useEffect(() => {
    fetch(`http://localhost:5000/api/jobs/${id}`)
      .then((res) => res.json())
      .then((data) => setJob(data))
      .catch((err) => console.error("Erreur:", err));
  }, [id]);

  const handleApplyClick = () => {
    fileInputRef.current.click();
  };

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const payload = { 
        cvBase64: reader.result, 
        fileName: file.name 
      };

      try {
        // Axios envoie automatiquement le bon Content-Type et stringifie le JSON
        const res = await axios.post(`http://localhost:5000/api/apply/${id}`, payload);
        
        alert("Candidature envoyée avec succès !");
        console.log("Réponse serveur :", res.data);
      } catch (err) {
        console.error("Erreur axios :", err.response?.data || err.message);
        alert("Erreur : " + (err.response?.data?.error || "Problème d'envoi"));
      }
    };
    
    reader.onerror = () => console.error("Erreur lors de la lecture du fichier");
    reader.readAsDataURL(file);
  };

  if (!job) return <p className="details-loading">Chargement des détails...</p>;

  return (
    <div className="details-container">
      <button className="btn-back" onClick={() => navigate(-1)}>← Retour</button>
      <h1 className="details-title">{job.title}</h1>
      <h3 className="details-company">{job.company}</h3>
      <p className="details-description">{job.description}</p>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        style={{ display: 'none' }} 
        accept=".pdf,.doc,.docx"
      />

      <button className="btn-apply" onClick={handleApplyClick}>
        Postuler à cette offre
      </button>
    </div>
  );
}
